contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        // Precondition: the test contract is not the keeper (it was set in constructor of C as deployer, this contract)
        // Actually, since this contract deployed c, it is owner and keeper is set during initialization.
        // To ensure the caller is not the keeper, we just call unpauseDeposit from this contract,
        // which is the deployer, but keeper was set during initialize to some other address (the _keeper param).
        // However, we cannot know the keeper address. But we can be sure that this contract is not the keeper
        // if the keeper was set to a different address during initialization. The test contract deployer is
        // not necessarily the keeper. The only safe assumption: the deployer is the owner, not necessarily the keeper.
        // But we cannot guarantee that. To make a general rule, we need to know that the msg.sender is not keeper.
        // Since we cannot read keeper directly (it is public, so we can!), we can read it: c.keeper() returns address.
        // But we cannot change the fact that this contract may be the keeper. So we require that it is not.
        // However, the keeper is set during initialization; we don't know its value. But the test is run on a fresh c
        // where the deployer (this contract) passed a _keeper address. In the test template, the constructor takes c already deployed.
        // We have no control over the initialization parameters. So we cannot guarantee that this contract is not the keeper.
        // But we can check: c.keeper() != address(this). If it is, then the call would succeed, violating our rule.
        // So we need to ensure the precondition that the caller is not the keeper.
        // Since we are the caller (msg.sender is this contract), we require that c.keeper() != address(this).
        require(c.keeper() != address(this), "caller is keeper");

        bool reverted;
        try c.unpauseDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == true);
    }
}

contract InvMutTest {
