    function run(bool callerIsKeeper) public {
        address currentKeeper = c.keeper();
        bool pausedBefore = c.paused();
        require(!pausedBefore, "contract must start paused for this rule");
        require(callerIsKeeper ? address(this) == currentKeeper : address(this) != currentKeeper, "caller role contradicts keeper");

        bool reverted;
        try c.unpauseDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !callerIsKeeper && c.paused() == callerIsKeeper);
    }
}

